# ============================================================================
#  Fleur de peau Cosmetique - Commande directe PC/TV + suivi de commande admin
#
#  Ce que ce script ajoute :
#   - Sur PC ou TV (pas mobile/tablette), le bouton de commande n'ouvre plus WhatsApp :
#     la commande est enregistree directement dans le systeme et visible dans l'admin.
#   - Sur mobile et tablette : rien ne change, le parcours WhatsApp reste identique.
#   - Dans l'admin > Commandes : chaque ligne peut maintenant s'ouvrir pour voir les
#     articles, le lieu de livraison et le telephone du client, en plus du suivi de
#     statut deja existant (en attente / confirmee / expediee / livree / annulee).
#
#  Utilisation :
#    1) Clic droit sur ce fichier > "Executer avec PowerShell"
#       (ou dans un terminal PowerShell ouvert a la racine du projet :
#        .\commande-directe-pc.ps1)
#    2) Repondre "o" a la question finale pour committer + pousser.
# ============================================================================

$ErrorActionPreference = "Stop"

$repoRoot = Get-Location
Write-Host "Dossier courant : $repoRoot" -ForegroundColor Cyan
Write-Host ""

function Write-FileFromBase64($relativePath, $base64Content) {
    $fullPath = Join-Path $repoRoot $relativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $bytes = [Convert]::FromBase64String($base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "  OK  $relativePath ($($bytes.Length) octets)" -ForegroundColor Green
}

Write-Host "Ecriture des fichiers..." -ForegroundColor Cyan

